<?php declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; $lh_page_title='Learning Hub'; $lh_description='Practical computer, programming, AI and digital skills with SmartToolz Learning Hub.'; $courses=[];$cats=[];$user=lh_user(); try{$courses=$db->query("SELECT c.*,lc.name category_name,lc.icon category_icon,(SELECT COUNT(*) FROM learning_lessons l WHERE l.course_id=c.id AND l.enabled=1) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);$cats=$db->query("SELECT * FROM learning_categories WHERE enabled=1 ORDER BY sort_order,name")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());} include __DIR__.'/includes/header.php'; include __DIR__.'/includes/navbar.php'; ?><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php'; ?></div><main class="col-lg-9 col-xl-10 lh-content py-4 py-lg-5"><div class="container-fluid"><section class="lh-hero p-4 p-md-5 mb-4"><span class="badge text-bg-primary mb-3">🎓 SmartToolz Learning Hub</span><h1 class="display-5 fw-bold">Learn skills. Build real things.</h1><p class="lead text-secondary mb-4">Practical lessons, exercises and projects for computer skills, web development, programming, AI and more.</p><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary" href="/learning-hub/courses.php">Browse Courses</a><a class="btn btn-outline-primary" href="/smart-toolz/">Explore Smart Tools</a></div></section><div class="row g-3 mb-5"><?php foreach($cats as $cat): ?><div class="col-6 col-md-4 col-xl-3"><a class="lh-card d-block p-3 h-100" href="/learning-hub/courses.php?category=<?=rawurlencode($cat['slug'])?>"><div class="fs-3 mb-2"><?=lh_h($cat['icon']??'📚')?></div><strong><?=lh_h($cat['name'])?></strong><div class="small text-secondary mt-1"><?=lh_h($cat['description']??'Learn practical skills.')?></div></a></div><?php endforeach; ?></div><div class="d-flex justify-content-between align-items-end mb-3"><div><h2 class="h3 mb-1">Featured courses</h2><p class="text-secondary mb-0">Choose a structured path and start learning.</p></div><a href="/learning-hub/courses.php" class="btn btn-sm btn-outline-primary">View all</a></div><div class="row g-3"><?php foreach(array_slice($courses,0,6) as $c): ?><div class="col-md-6 col-xl-4"><a class="lh-card d-flex flex-column h-100 p-4" href="/learning-hub/course.php?slug=<?=rawurlencode($c['slug'])?>"><div class="fs-2"><?=lh_h($c['category_icon']??'📚')?></div><h3 class="h5 mt-3 mb-2"><?=lh_h($c['title'])?></h3><p class="text-secondary small"><?=lh_h($c['description']??'Practical course with step-by-step lessons.')?></p><div class="mt-auto pt-3 d-flex justify-content-between small fw-semibold"><span><?=lh_h($c['level'])?></span><span><?=number_format((int)$c['lesson_count'])?> lessons →</span></div></a></div><?php endforeach; if(!$courses): ?><div class="col-12"><div class="alert alert-light border">Courses are being prepared. Please check back shortly.</div></div><?php endif; ?></div><section class="lh-card p-4 p-md-5 mt-5"><div class="row align-items-center g-3"><div class="col-lg-8"><h2 class="h4">Practice what you learn</h2><p class="text-secondary mb-0">Use SmartToolz alongside your lessons and turn concepts into practical work.</p></div><div class="col-lg-4 text-lg-end"><a class="btn btn-primary" href="/smart-toolz/">Explore Smart Tools →</a></div></div></section><div class="lh-ad-slot my-5">Advertisement</div></div></main></div></div><?php include __DIR__.'/includes/footer.php'; ?><script src="/learning-hub/assets/js/app.js"></script>